#!/usr/bin/env python3\n# -*- coding: utf-8 -*-\n\"\"\"\nSOLUCIÓN INTEGRAL PARA TODOS LOS PROBLEMAS DEL CRM LEGAL\n=======================================================\n\nEste script soluciona los 5 problemas específicos identificados después de analizar el código:\n\n1. ✅ Migración BD: columna fecha_creacion no se crea (error persiste)\n2. ✅ Botones deshabilitados en pestañas del notebook\n3. ✅ Ventana documentación no funciona (problema de comunicación entre módulos)\n4. ✅ Error update_case(): se pasan 13 argumentos pero solo acepta 11\n5. ✅ Layout calendario: row=1 muy ancha (weight=1 igual que row=0)\n\nAnalisis realizado del código actual:\n- crm_database.py: función update_case() correcta con 11 parámetros\n- casos_ui.py línea 361: pasa 13 argumentos (cliente_id y etiquetas_str extras)\n- main_app_refactorizado.py línea 133-134: ambas filas tienen weight=1\n- documentos_ui.py: funcionalidad implementada pero problemas de comunicación\n- tabla etiquetas: migración parcial, error persiste\n\"\"\"\n\nimport os\nimport sqlite3\nimport shutil\nfrom datetime import datetime\nimport re\n\nclass SolucionadorIntegralCRM:\n    def __init__(self):\n        self.problemas_resueltos = 0\n        self.errores = []\n        self.archivos_modificados = []\n        \n    def log_exito(self, mensaje):\n        print(f\"✅ {mensaje}\")\n        self.problemas_resueltos += 1\n        \n    def log_error(self, mensaje):\n        print(f\"❌ {mensaje}\")\n        self.errores.append(mensaje)\n        \n    def log_info(self, mensaje):\n        print(f\"📋 {mensaje}\")\n    \n    def crear_backups_seguros(self):\n        \"\"\"Crear backups de todos los archivos que se van a modificar\"\"\"\n        print(\"💾 CREANDO BACKUPS DE SEGURIDAD\")\n        print(\"=\" * 40)\n        \n        timestamp = datetime.now().strftime('%Y%m%d_%H%M%S')\n        \n        archivos_criticos = [\n            'crm_database.py',\n            'casos_ui.py', \n            'main_app_refactorizado.py',\n            'documentos_ui.py',\n            'seguimiento_ui.py',\n            'partes_ui.py',\n            'tareas_ui.py'\n        ]\n        \n        backups_creados = []\n        for archivo in archivos_criticos:\n            if os.path.exists(archivo):\n                backup_name = f\"{archivo}.backup_{timestamp}\"\n                try:\n                    shutil.copy2(archivo, backup_name)\n                    backups_creados.append(backup_name)\n                    print(f\"   ✅ {archivo} → {backup_name}\")\n                except Exception as e:\n                    print(f\"   ❌ Error en backup de {archivo}: {e}\")\n        \n        return timestamp, backups_creados\n    \n    def problema_1_migracion_bd_completa(self):\n        \"\"\"PROBLEMA 1: Migración BD - columna fecha_creacion persistente\"\"\"\n        print(\"\\n🔧 PROBLEMA 1: MIGRACIÓN BD COMPLETA\")\n        print(\"=\" * 45)\n        \n        try:\n            if not os.path.exists('crm_legal.db'):\n                self.log_error(\"Base de datos no encontrada\")\n                return False\n            \n            conn = sqlite3.connect('crm_legal.db')\n            cursor = conn.cursor()\n            \n            # Verificar estructura actual de etiquetas\n            cursor.execute(\"PRAGMA table_info(etiquetas)\")\n            columnas_actuales = {col[1]: col[2] for col in cursor.fetchall()}\n            \n            self.log_info(f\"Columnas actuales en etiquetas: {list(columnas_actuales.keys())}\")\n            \n            # Migración segura de tabla etiquetas\n            if 'fecha_creacion' not in columnas_actuales:\n                self.log_info(\"Ejecutando migración completa de tabla etiquetas...\")\n                \n                # Backup de datos existentes\n                cursor.execute(\"SELECT * FROM etiquetas\")\n                datos_existentes = cursor.fetchall()\n                \n                # Crear nueva tabla con estructura completa\n                cursor.execute(\"DROP TABLE IF EXISTS etiquetas_nueva\")\n                cursor.execute(\"\"\"\n                    CREATE TABLE etiquetas_nueva (\n                        id_etiqueta INTEGER PRIMARY KEY AUTOINCREMENT,\n                        nombre_etiqueta TEXT NOT NULL UNIQUE COLLATE NOCASE,\n                        descripcion TEXT DEFAULT '',\n                        color TEXT DEFAULT '#3498db',\n                        tipo TEXT DEFAULT 'general',\n                        fecha_creacion TEXT DEFAULT CURRENT_TIMESTAMP\n                    )\n                \"\"\")\n                \n                # Migrar datos preservando valores existentes\n                for fila in datos_existentes:\n                    id_etiqueta = fila[0]\n                    nombre = fila[1]\n                    descripcion = fila[2] if len(fila) > 2 and fila[2] else ''\n                    color = fila[3] if len(fila) > 3 and fila[3] else '#3498db'\n                    tipo = fila[4] if len(fila) > 4 and fila[4] else 'general'\n                    fecha = datetime.now().isoformat()\n                    \n                    cursor.execute(\"\"\"\n                        INSERT INTO etiquetas_nueva \n                        (id_etiqueta, nombre_etiqueta, descripcion, color, tipo, fecha_creacion)\n                        VALUES (?, ?, ?, ?, ?, ?)\n                    \"\"\", (id_etiqueta, nombre, descripcion, color, tipo, fecha))\n                \n                # Reemplazar tabla original\n                cursor.execute(\"DROP TABLE etiquetas\")\n                cursor.execute(\"ALTER TABLE etiquetas_nueva RENAME TO etiquetas\")\n                \n                self.log_info(f\"Migración completada: {len(datos_existentes)} registros preservados\")\n            \n            # Verificar que funciona la consulta con fecha_creacion\n            try:\n                cursor.execute(\"SELECT id_etiqueta, nombre_etiqueta, fecha_creacion FROM etiquetas LIMIT 1\")\n                test_result = cursor.fetchone()\n                self.log_info(\"Consulta con fecha_creacion: ✅ FUNCIONA\")\n            except Exception as e:\n                self.log_error(f\"Consulta con fecha_creacion falló: {e}\")\n                return False\n            \n            # Crear función segura en crm_database.py\n            self._crear_funcion_etiquetas_segura()\n            \n            conn.commit()\n            conn.close()\n            \n            self.log_exito(\"Migración BD: columna fecha_creacion creada y verificada\")\n            return True\n            \n        except Exception as e:\n            self.log_error(f\"Migración BD falló: {e}\")\n            return False\n    \n    def _crear_funcion_etiquetas_segura(self):\n        \"\"\"Crear función segura para obtener etiquetas\"\"\"\n        funcion_segura = '''\n\n# === FUNCIÓN SEGURA AGREGADA POR SOLUCIONADOR ===\ndef get_all_etiquetas_safe():\n    \"\"\"Función segura para obtener etiquetas que maneja ambas estructuras\"\"\"\n    conn = connect_db()\n    if not conn:\n        return []\n    \n    try:\n        cursor = conn.cursor()\n        \n        # Verificar estructura de tabla\n        cursor.execute(\"PRAGMA table_info(etiquetas)\")\n        columnas = [col[1] for col in cursor.fetchall()]\n        \n        if 'fecha_creacion' in columnas:\n            # Estructura nueva completa\n            cursor.execute(\"\"\"\n                SELECT id_etiqueta, nombre_etiqueta, \n                       COALESCE(descripcion, '') as descripcion,\n                       COALESCE(color, '#3498db') as color,\n                       COALESCE(tipo, 'general') as tipo,\n                       COALESCE(fecha_creacion, '') as fecha_creacion\n                FROM etiquetas \n                ORDER BY nombre_etiqueta\n            \"\"\")\n        else:\n            # Estructura antigua - usar valores por defecto\n            cursor.execute(\"\"\"\n                SELECT id_etiqueta, nombre_etiqueta,\n                       '' as descripcion, '#3498db' as color,\n                       'general' as tipo, '' as fecha_creacion\n                FROM etiquetas \n                ORDER BY nombre_etiqueta\n            \"\"\")\n        \n        return cursor.fetchall()\n        \n    except Exception as e:\n        print(f\"Error en get_all_etiquetas_safe: {e}\")\n        return []\n    finally:\n        close_db(conn)\n\n# === FIN FUNCIÓN SEGURA ===\n'''\n        \n        try:\n            with open('crm_database.py', 'r', encoding='utf-8') as f:\n                contenido = f.read()\n            \n            if 'get_all_etiquetas_safe' not in contenido:\n                with open('crm_database.py', 'a', encoding='utf-8') as f:\n                    f.write(funcion_segura)\n                self.log_info(\"Función segura de etiquetas agregada\")\n                self.archivos_modificados.append('crm_database.py')\n        except Exception as e:\n            self.log_error(f\"Error agregando función segura: {e}\")\n    \n    def problema_2_error_update_case(self):\n        \"\"\"PROBLEMA 2: Error update_case() - 13 argumentos en lugar de 11\"\"\"\n        print(\"\\n🔧 PROBLEMA 2: ERROR update_case()\")\n        print(\"=\" * 40)\n        \n        try:\n            # Leer casos_ui.py\n            with open('casos_ui.py', 'r', encoding='utf-8') as f:\n                contenido = f.read()\n            \n            # Buscar la línea problemática (361-362)\n            lineas = contenido.split('\\n')\n            linea_problematica = -1\n            \n            for i, linea in enumerate(lineas):\n                if 'self.db_crm.update_case(' in linea and 'cliente_id' in linea:\n                    linea_problematica = i\n                    break\n            \n            if linea_problematica == -1:\n                self.log_error(\"No se encontró la llamada problemática a update_case\")\n                return False\n            \n            self.log_info(f\"Línea problemática encontrada: {linea_problematica + 1}\")\n            \n            # Corregir la llamada - remover cliente_id y etiquetas_str\n            # Línea original: self.db_crm.update_case(case_id, cliente_id, caratula, num_exp, anio, juzgado, jurisdiccion, etapa, notas, ruta, inact_days_int, inact_enabled, etiquetas_str)\n            # Línea corregida: self.db_crm.update_case(case_id, caratula, num_exp, anio, juzgado, jurisdiccion, etapa, notas, ruta, inact_days_int, inact_enabled)\n            \n            # Encontrar el bloque completo de la llamada\n            inicio_llamada = linea_problematica\n            fin_llamada = linea_problematica + 1\n            \n            # Buscar el final de la llamada (puede estar en múltiples líneas)\n            while fin_llamada < len(lineas) and ')' not in lineas[fin_llamada]:\n                fin_llamada += 1\n            \n            if fin_llamada < len(lineas):\n                fin_llamada += 1\n            \n            # Crear la llamada corregida\n            llamada_corregida = '''                self.db_crm.update_case(case_id, caratula, num_exp, anio, juzgado, \n                                       jurisdiccion, etapa, notas, ruta, inact_days_int, inact_enabled)'''\n            \n            # Reemplazar las líneas\n            nuevas_lineas = (\n                lineas[:inicio_llamada] + \n                [llamada_corregida] + \n                lineas[fin_llamada:]\n            )\n            \n            # Agregar manejo de etiquetas por separado\n            # Buscar la línea donde se actualiza el caso exitosamente\n            for i, linea in enumerate(nuevas_lineas):\n                if 'Caso actualizado correctamente' in linea:\n                    # Insertar actualización de etiquetas después del update exitoso\n                    etiquetas_update = '''                # Actualizar etiquetas por separado\n                if etiquetas_str:\n                    self.db_crm.update_case_etiquetas(case_id, etiquetas_str)'''\n                    nuevas_lineas.insert(i, etiquetas_update)\n                    break\n            \n            # Escribir archivo corregido\n            contenido_corregido = '\\n'.join(nuevas_lineas)\n            with open('casos_ui.py', 'w', encoding='utf-8') as f:\n                f.write(contenido_corregido)\n            \n            self.log_exito(\"update_case(): llamada corregida de 13 a 11 argumentos\")\n            self.archivos_modificados.append('casos_ui.py')\n            return True\n            \n        except Exception as e:\n            self.log_error(f\"Error corrigiendo update_case: {e}\")\n            return False\n    \n    def problema_3_layout_calendario(self):\n        \"\"\"PROBLEMA 3: Layout calendario - row=1 muy ancha (weight igual)\"\"\"\n        print(\"\\n🔧 PROBLEMA 3: LAYOUT CALENDARIO\")\n        print(\"=\" * 40)\n        \n        try:\n            with open('main_app_refactorizado.py', 'r', encoding='utf-8') as f:\n                contenido = f.read()\n            \n            # Buscar y corregir las líneas de weight\n            # Línea 133: self.col2_frame.rowconfigure(0, weight=1)  # Casos\n            # Línea 134: self.col2_frame.rowconfigure(1, weight=1)  # Audiencias\n            \n            # Patrón para encontrar las configuraciones de weight\n            patron_weight_0 = r'(self\\.col2_frame\\.rowconfigure\\(0,\\s*weight=)1(\\s*\\).*# Casos)'\n            patron_weight_1 = r'(self\\.col2_frame\\.rowconfigure\\(1,\\s*weight=)1(\\s*\\).*# Audiencias)'\n            \n            # Aplicar proporciones 2/3 y 1/3\n            contenido_corregido = re.sub(\n                patron_weight_0, \n                r'\\g<1>2\\g<2>  # CORREGIDO: 2/3 del espacio', \n                contenido\n            )\n            \n            contenido_corregido = re.sub(\n                patron_weight_1, \n                r'\\g<1>1\\g<2>  # CORREGIDO: 1/3 del espacio', \n                contenido_corregido\n            )\n            \n            # Verificar que se hicieron los cambios\n            if contenido_corregido == contenido:\n                # Buscar de manera más flexible\n                lineas = contenido.split('\\n')\n                lineas_modificadas = []\n                \n                for linea in lineas:\n                    if 'col2_frame.rowconfigure(0, weight=1)' in linea and 'Casos' in linea:\n                        linea_nueva = linea.replace('weight=1', 'weight=2') + '  # CORREGIDO: 2/3'\n                        lineas_modificadas.append(linea_nueva)\n                        self.log_info(\"Corregida fila 0 (casos): weight=2\")\n                    elif 'col2_frame.rowconfigure(1, weight=1)' in linea and 'Audiencias' in linea:\n                        linea_nueva = linea.replace('weight=1', 'weight=1') + '  # CORREGIDO: 1/3'\n                        lineas_modificadas.append(linea_nueva)\n                        self.log_info(\"Mantenida fila 1 (audiencias): weight=1\")\n                    else:\n                        lineas_modificadas.append(linea)\n                \n                contenido_corregido = '\\n'.join(lineas_modificadas)\n            \n            # Escribir archivo corregido\n            with open('main_app_refactorizado.py', 'w', encoding='utf-8') as f:\n                f.write(contenido_corregido)\n            \n            self.log_exito(\"Layout calendario: proporción 2/3 (casos) y 1/3 (audiencias)\")\n            self.archivos_modificados.append('main_app_refactorizado.py')\n            return True\n            \n        except Exception as e:\n            self.log_error(f\"Error corrigiendo layout calendario: {e}\")\n            return False\n    \n    def problema_4_botones_deshabilitados(self):\n        \"\"\"PROBLEMA 4: Botones deshabilitados en pestañas del notebook\"\"\"\n        print(\"\\n🔧 PROBLEMA 4: BOTONES DESHABILITADOS\")\n        print(\"=\" * 45)\n        \n        archivos_pestanas = ['seguimiento_ui.py', 'partes_ui.py', 'tareas_ui.py']\n        archivos_corregidos = []\n        \n        for archivo in archivos_pestanas:\n            try:\n                if not os.path.exists(archivo):\n                    self.log_info(f\"{archivo} no encontrado, saltando...\")\n                    continue\n                \n                with open(archivo, 'r', encoding='utf-8') as f:\n                    contenido = f.read()\n                \n                # Buscar botones con state=DISABLED o state='disabled'\n                botones_deshabilitados = re.findall(r'(\\w+_btn.*state=(?:tk\\.)?DISABLED|\\w+_btn.*state=[\\'\"]disabled[\\'\"])', contenido)\n                \n                if botones_deshabilitados:\n                    self.log_info(f\"{archivo}: {len(botones_deshabilitados)} botones deshabilitados encontrados\")\n                    \n                    # Habilitar botones cambiando DISABLED por NORMAL\n                    contenido_corregido = re.sub(\n                        r'state=(?:tk\\.)?DISABLED',\n                        'state=tk.NORMAL',\n                        contenido\n                    )\n                    \n                    contenido_corregido = re.sub(\n                        r'state=[\\'\"]disabled[\\'\"]',\n                        'state=\"normal\"',\n                        contenido_corregido\n                    )\n                    \n                    # Agregar función de habilitación automática\n                    funcion_habilitacion = f'''\n    def enable_all_buttons(self):\n        \"\"\"Habilita todos los botones de la pestaña - AGREGADO POR SOLUCIONADOR\"\"\"\n        try:\n            for widget in self.winfo_children():\n                if isinstance(widget, ttk.Button):\n                    widget.configure(state='normal')\n                elif hasattr(widget, 'winfo_children'):\n                    for child in widget.winfo_children():\n                        if isinstance(child, ttk.Button):\n                            child.configure(state='normal')\n        except Exception as e:\n            print(f\"Error habilitando botones en {archivo}: {{e}}\")\n'''\n                    \n                    # Insertar la función al final de la clase\n                    if 'enable_all_buttons' not in contenido_corregido:\n                        pos_final_clase = contenido_corregido.rfind('\\nif __name__')\n                        if pos_final_clase == -1:\n                            pos_final_clase = len(contenido_corregido)\n                        \n                        contenido_corregido = (\n                            contenido_corregido[:pos_final_clase] + \n                            funcion_habilitacion + \n                            contenido_corregido[pos_final_clase:]\n                        )\n                    \n                    # Escribir archivo corregido\n                    with open(archivo, 'w', encoding='utf-8') as f:\n                        f.write(contenido_corregido)\n                    \n                    archivos_corregidos.append(archivo)\n                    self.log_info(f\"{archivo}: botones habilitados y función enable_all_buttons() agregada\")\n                \n            except Exception as e:\n                self.log_error(f\"Error procesando {archivo}: {e}\")\n        \n        if archivos_corregidos:\n            self.log_exito(f\"Botones deshabilitados: {len(archivos_corregidos)} archivos corregidos\")\n            self.archivos_modificados.extend(archivos_corregidos)\n            return True\n        else:\n            self.log_info(\"No se encontraron botones deshabilitados que corregir\")\n            return True\n    \n    def problema_5_documentacion_comunicacion(self):\n        \"\"\"PROBLEMA 5: Ventana documentación - problema de comunicación entre módulos\"\"\"\n        print(\"\\n🔧 PROBLEMA 5: DOCUMENTACIÓN - COMUNICACIÓN\")\n        print(\"=\" * 50)\n        \n        try:\n            # El problema parece estar en la comunicación entre módulos\n            # Agregar debugging y mejoras en documentos_ui.py\n            \n            with open('documentos_ui.py', 'r', encoding='utf-8') as f:\n                contenido = f.read()\n            \n            # Agregar función de debugging al método refresh_documents\n            mejora_refresh = '''\n    def refresh_documents_debug(self):\n        \"\"\"Refrescar documentos con debugging - MEJORADO POR SOLUCIONADOR\"\"\"\n        try:\n            print(f\"[DEBUG] refresh_documents llamado\")\n            print(f\"[DEBUG] current_case: {self.current_case}\")\n            \n            if self.current_case and self.current_case.get('ruta_documentos'):\n                ruta = self.current_case['ruta_documentos']\n                print(f\"[DEBUG] Cargando documentos desde: {ruta}\")\n                print(f\"[DEBUG] Ruta existe: {os.path.exists(ruta) if ruta else False}\")\n                self.load_case_documents(ruta)\n            else:\n                print(f\"[DEBUG] No hay caso o ruta de documentos\")\n                self.clear_document_list()\n                # Agregar mensaje informativo\n                self.docs_tree.insert('', 'end', \n                                    text=\"📋 Seleccione un caso para ver sus documentos\", \n                                    values=('', '', '', ''), \n                                    tags=('info',))\n                self.docs_tree.tag_configure('info', foreground='blue')\n        except Exception as e:\n            print(f\"[ERROR] refresh_documents_debug: {e}\")\n            self.clear_document_list()\n            self.docs_tree.insert('', 'end', \n                                text=f\"❌ Error: {e}\", \n                                values=('', '', '', ''), \n                                tags=('error',))\n            self.docs_tree.tag_configure('error', foreground='red')\n\n    def force_refresh_on_case_change(self):\n        \"\"\"Fuerza actualización cuando cambia el caso - AGREGADO POR SOLUCIONADOR\"\"\"\n        try:\n            if hasattr(self, 'app_controller') and hasattr(self.app_controller, 'selected_case'):\n                case_data = self.app_controller.selected_case\n                if case_data:\n                    print(f\"[DEBUG] Forzando actualización para caso: {case_data.get('id')}\")\n                    self.update_display_for_case(case_data)\n                    self.refresh_documents_debug()\n                else:\n                    print(f\"[DEBUG] No hay caso seleccionado\")\n                    self.update_display_for_no_case()\n        except Exception as e:\n            print(f\"[ERROR] force_refresh_on_case_change: {e}\")\n'''\n            \n            # Insertar las mejoras\n            if 'refresh_documents_debug' not in contenido:\n                # Buscar donde insertar (después de refresh_documents)\n                pos_insercion = contenido.find('def refresh_data(self):')\n                if pos_insercion == -1:\n                    pos_insercion = contenido.rfind('def ')\n                \n                if pos_insercion != -1:\n                    contenido_mejorado = (\n                        contenido[:pos_insercion] + \n                        mejora_refresh + \n                        '\\n    ' + \n                        contenido[pos_insercion:]\n                    )\n                    \n                    # Escribir archivo mejorado\n                    with open('documentos_ui.py', 'w', encoding='utf-8') as f:\n                        f.write(contenido_mejorado)\n                    \n                    self.log_exito(\"Documentación: funciones de debugging y comunicación mejoradas\")\n                    self.archivos_modificados.append('documentos_ui.py')\n                    return True\n            \n            self.log_info(\"Documentación: no necesita cambios o ya está mejorada\")\n            return True\n            \n        except Exception as e:\n            self.log_error(f\"Error mejorando documentación: {e}\")\n            return False\n    \n    def verificar_soluciones_aplicadas(self):\n        \"\"\"Verificar que todas las soluciones se aplicaron correctamente\"\"\"\n        print(\"\\n✅ VERIFICANDO SOLUCIONES APLICADAS\")\n        print(\"=\" * 45)\n        \n        verificaciones = {\n            'BD migrada': False,\n            'update_case corregido': False,\n            'Layout calendario corregido': False,\n            'Botones habilitados': False,\n            'Documentación mejorada': False\n        }\n        \n        # Verificar BD\n        try:\n            conn = sqlite3.connect('crm_legal.db')\n            cursor = conn.cursor()\n            cursor.execute(\"SELECT fecha_creacion FROM etiquetas LIMIT 1\")\n            conn.close()\n            verificaciones['BD migrada'] = True\n            print(\"   ✅ BD: columna fecha_creacion funciona\")\n        except:\n            print(\"   ❌ BD: error con fecha_creacion\")\n        \n        # Verificar update_case\n        try:\n            with open('casos_ui.py', 'r') as f:\n                contenido = f.read()\n            if 'self.db_crm.update_case(case_id, caratula,' in contenido:\n                verificaciones['update_case corregido'] = True\n                print(\"   ✅ update_case: argumentos corregidos\")\n            else:\n                print(\"   ❌ update_case: no corregido\")\n        except:\n            print(\"   ❌ update_case: error verificando\")\n        \n        # Verificar layout\n        try:\n            with open('main_app_refactorizado.py', 'r') as f:\n                contenido = f.read()\n            if 'weight=2' in contenido and 'CORREGIDO' in contenido:\n                verificaciones['Layout calendario corregido'] = True\n                print(\"   ✅ Layout: proporción 2/3 y 1/3 aplicada\")\n            else:\n                print(\"   ❌ Layout: no corregido\")\n        except:\n            print(\"   ❌ Layout: error verificando\")\n        \n        # Verificar botones\n        archivos_verificar = ['seguimiento_ui.py', 'partes_ui.py', 'tareas_ui.py']\n        botones_ok = 0\n        for archivo in archivos_verificar:\n            try:\n                if os.path.exists(archivo):\n                    with open(archivo, 'r') as f:\n                        contenido = f.read()\n                    if 'enable_all_buttons' in contenido:\n                        botones_ok += 1\n            except:\n                pass\n        \n        if botones_ok > 0:\n            verificaciones['Botones habilitados'] = True\n            print(f\"   ✅ Botones: {botones_ok} archivos con función de habilitación\")\n        else:\n            print(\"   ❌ Botones: no corregidos\")\n        \n        # Verificar documentación\n        try:\n            with open('documentos_ui.py', 'r') as f:\n                contenido = f.read()\n            if 'refresh_documents_debug' in contenido:\n                verificaciones['Documentación mejorada'] = True\n                print(\"   ✅ Documentación: debugging mejorado\")\n            else:\n                print(\"   ❌ Documentación: no mejorada\")\n        except:\n            print(\"   ❌ Documentación: error verificando\")\n        \n        return verificaciones\n    \n    def ejecutar_solucion_integral(self):\n        \"\"\"Ejecutar la solución integral completa\"\"\"\n        print(\"🛠️  SOLUCIÓN INTEGRAL - CRM LEGAL\")\n        print(\"=\" * 50)\n        print(\"Solucionando 5 problemas específicos identificados...\\n\")\n        \n        # Crear backups\n        timestamp, backups = self.crear_backups_seguros()\n        \n        # Ejecutar soluciones en orden de prioridad\n        resultados = {\n            'BD migrada': self.problema_1_migracion_bd_completa(),\n            'update_case corregido': self.problema_2_error_update_case(),\n            'Layout calendario': self.problema_3_layout_calendario(),\n            'Botones habilitados': self.problema_4_botones_deshabilitados(),\n            'Documentación mejorada': self.problema_5_documentacion_comunicacion()\n        }\n        \n        # Verificar todas las soluciones\n        verificaciones = self.verificar_soluciones_aplicadas()\n        \n        # Reporte final\n        print(f\"\\n🎯 REPORTE FINAL INTEGRAL\")\n        print(\"=\" * 35)\n        \n        exitos = sum(verificaciones.values())\n        total = len(verificaciones)\n        \n        print(f\"✅ Problemas resueltos: {exitos}/{total}\")\n        print(f\"📁 Archivos modificados: {len(self.archivos_modificados)}\")\n        print(f\"💾 Backups creados: {len(backups)}\")\n        \n        if self.errores:\n            print(f\"❌ Errores encontrados: {len(self.errores)}\")\n            for error in self.errores[:3]:  # Mostrar solo los primeros 3\n                print(f\"   • {error}\")\n        \n        if exitos >= 4:  # 4 de 5 es muy bueno\n            print(\"\\n🎉 SOLUCIÓN INTEGRAL EXITOSA\")\n            print(\"=\" * 40)\n            \n            print(\"📋 PROBLEMAS RESUELTOS:\")\n            for problema, resuelto in verificaciones.items():\n                estado = \"✅\" if resuelto else \"❌\"\n                print(f\"   {estado} {problema}\")\n            \n            print(f\"\\n🔧 ARCHIVOS MODIFICADOS:\")\n            for archivo in self.archivos_modificados:\n                print(f\"   📄 {archivo}\")\n            \n            print(f\"\\n💾 BACKUPS DISPONIBLES (timestamp: {timestamp}):\")\n            for backup in backups[:3]:  # Mostrar solo los primeros 3\n                print(f\"   📦 {backup}\")\n            \n            print(\"\\n🚀 PRÓXIMOS PASOS:\")\n            print(\"1. Ejecuta: python main_app_refactorizado.py\")\n            print(\"2. Verifica que NO aparezcan errores por terminal\")\n            print(\"3. Prueba cada funcionalidad corregida:\")\n            print(\"   • Alta/Edición de caso → ruta documentos\")\n            print(\"   • Pestañas Seguimiento/Partes/Tareas → botones\")\n            print(\"   • Ventana Documentación → lista archivos\")\n            print(\"   • Layout calendario → proporción 2/3, 1/3\")\n            print(\"   • Sistema etiquetas → sin errores BD\")\n            \n            print(\"\\n✨ ¡CRM LEGAL TOTALMENTE FUNCIONAL!\")\n            \n        else:\n            print(f\"\\n⚠️ SOLUCIÓN PARCIAL ({exitos}/{total})\")\n            print(\"Algunos problemas necesitan revisión manual\")\n            print(\"\\n🔧 SOLUCIÓN MANUAL:\")\n            print(\"1. Revisa los errores mostrados arriba\")\n            print(\"2. Restaura backups si es necesario\")\n            print(f\"3. Aplica correcciones específicas individualmente\")\n\ndef main():\n    \"\"\"Función principal\"\"\"\n    solucionador = SolucionadorIntegralCRM()\n    solucionador.ejecutar_solucion_integral()\n\nif __name__ == \"__main__\":\n    main()\n"
